import unittest,re
from tools.kjv_archive import load_register,read
class LukeSharedObligationTests(unittest.TestCase):
 def test_shared_obligation_and_uneven_voices(self):
  prior,_=load_register('0.10-kjv.208');lang,manifest=load_register('0.10-kjv.209')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('luke-'):c for c in read(lang.folder/'luke-shared-obligation-and-uneven-voices-cases.json')};self.assertEqual(len(cases),80)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}&set(r['keys']))
