  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('ipl think:pr not',cases['17-9']['analysis'])
  self.assertIn('wesg not profitable servant:pl',cases['17-10']['analysis'])
  self.assertIn('kingdom of god within you',cases['17-21']['analysis'])
  self.assertIn('two man:pl in field',cases['17-36']['analysis'])
  self.assertIn('body',cases['17-37']['analysis'])
  self.assertNotIn('corpse',cases['17-37']['analysis'])
  self.assertIn('i twice in week',cases['18-12']['analysis'])
  self.assertIn('why ipl:a good',cases['18-19']['analysis'])
  self.assertIn('except one_num that god',cases['18-19']['analysis'])
  self.assertIn('many kjv_fold more',cases['18-30']['analysis'])
  self.assertIn('wesg to kjv_jerusalem',cases['18-31']['analysis'])
  self.assertIn('near to kjv_jericho',cases['18-35']['analysis'])
  self.assertNotIn('kjv_bartimaeus',cases['18-35']['analysis'])
  self.assertIn('ipl to thou',cases['18-41']['analysis'])
  self.assertIn('i my/sight',cases['18-41']['analysis'])
  self.assertEqual(lang.word('kjv_peter_disciple')[0],lang.maxima(lang.lexicon['kjv_peter_disciple']['form']))
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),1)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
